Given a string s, find a way to reverse the order of the words in the given string. Note: string may contain leading or trailing dots(.) or multiple trailing dots(.) between two words. The returned string should only have a single dot(.) separating the words.Examples:Input: s = "i.like.this.program.very.much" Output: much.very.program.this.like.iExplanation: The words in the input string are reversed while maintaining the dots as separators, resulting in "much.very.program.this.like.i".Input: s = ”..geeks..for.geeks.” Output: geeks.for.geeksInput: s = "...home......"Output: homeTry It YourselfTable of Content[Naive Approach] Using Stack - O(n) Time and O(n) Space[Expected Approach] Using Two Pointer - O(n) Time and O(1) Space[Alternate Approach] Using inbuilt library functions - O(n) Time and O(n) Space[Naive Approach] Using Stack - O(n) Time and O(n) SpacePush all words separated by dots into a stack, then pop each word one by one and append it back to form the reversed string.
            C++

    #include <iostream>
#include <stack>
#include <string>
using namespace std;

string reverseWords(string &s) {
    stack<string> st;
    string result = "";
    for (int i = 0; i < s.length(); i++) {

        if (s[i] != '.') {
            result += s[i];
        }

        // If we see a dot, we push the
        // previously seen word into the stack.
        else if (!result.empty()) {
            st.push(result);
            result = "";
        }
    }

    // Last word remaining, add it to stack
    if (!result.empty()) {
        st.push(result);
    }

    result = "";
    // Now add from top to bottom of the stack
    while (!st.empty()) {
        result += st.top();
        st.pop();
        if (!st.empty()) {
            result += ".";
        }
    }
    return result;
}

int main() {
    string s = "..geeks..for.geeks.";
    cout << reverseWords(s) << endl;
    return 0;
}


