    #include <iostream>
#include <sstream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

string reverseWords(string s) {

    vector<string> words;
    stringstream ss(s);
    string word;

    while (getline(ss, word, '.')) {
        if (!word.empty()) {
            words.push_back(word);
        }
    }

    reverse(words.begin(), words.end());

    string result;
    for (int i = 0; i < words.size(); ++i) {
        if (i > 0) {
            result += '.';
        }
        result += words[i];
    }

    return result;
}

